/bin/zsh -c "cat > /tmp/shop-verify.mjs <<'EOF'
import {spawn} from 'node:child_process';
import {gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
const child = spawn('bun', ['dist/server.mjs'], {stdio:['ignore','pipe','inherit']});
const port = await new Promise(resolve => child.stdout.once('data', data => resolve(Number(data.toString().trim()))));
const base = "'`http://127.0.0.1:${port}`;
const doc = text => Buffer.concat([Buffer.from('"'SHOPPDF'), gzipSync(text)]);
const post = async (id, body) => {const r = await fetch("'`${base}/upload?id=${id}`, {method:'"'POST', body}); return [r.status, await r.json(), r.headers.get('retry-after')];};
try {
 const good = await post('good', doc('<title>Supplies</title>'));
 const bad = Buffer.from('invalid');
 const failed = await post('bad', bad);
 const hash = await (await fetch("'`${base}/attachment?id=bad`)).text();
 const probe = await post('"'probe', doc('<probe/>'));
 const allocation = await post('allocation', doc('<allocate/>'));
 const oversized = await post('large', doc('<title>' + 'x'.repeat(1024*1024) + '</title>'));
 const slow = doc('<doc delay=\"1000\"><title>slow</title></doc>');
 const pending = [post('s1',slow),post('s2',slow),post('s3',slow)];
 await new Promise(r=>setTimeout(r,30));
 const health = await (await fetch("'`${base}/health`)).text();
 const busy = await post('"'s4',slow);
 const timed = await Promise.all(pending);
 console.log(JSON.stringify({good, failed, kept:hash===createHash('sha256').update(bad).digest('hex'), probe, allocation, oversized, health, busy, timed}));
 if (good[0]"'!==200 || failed[0]!==422 || hash!==createHash('"'sha256').update(bad).digest('hex') || probe[0]"'!==200 || allocation[0]!==422 || oversized[0]!==422 || health!=='"'alive' || busy[0]"'!==503 || timed.some(x=>x[0]!==422)) process.exitCode=1;
} finally {child.kill();}
EOF
bun /tmp/shop-verify.mjs'

